import{z as m,x as l,o as E,c as p,q as B,j as i,D as e,d as r,s as o,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"微观价格","description":"","frontmatter":{"title":"微观价格","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/microprice.md","filePath":"quant/microprice.md","lastUpdated":1791413859000}'),A={name:"quant/microprice.md"};function d(c,a,_,h,u,q){const s=l("Mermaid");return E(),p("div",null,[a[2]||(a[2]=B('<h1 id="微观价格" tabindex="-1">微观价格 <a class="header-anchor" href="#微观价格" aria-label="Permalink to &quot;微观价格&quot;">​</a></h1><div class="epigraph"><p>用两侧最优档的量去做权，中间价会被推向量更薄的一侧——下一步更可能被打穿的那一侧，而不是几何中点。</p><footer>—— 据 Stoikov 对 micro-price 的论述，以及 Cont 等人对限价簿几何与价格冲击的研究整理</footer></div><p><a href="/quant/hawkes-trades">上一课</a>把成交到达写成自激点过程，\\(\\lambda(t)=\\mu+\\int\\phi\\,\\mathrm{d}N\\)，分支比度量内生反馈；自激解释成串，不自动等于知情。缺口是报价读数：中间价默认两侧同样可能成为下一笔成交价，簿几乎从不对称，<a href="/quant/queue-imbalance-alpha">队列不平衡</a> 偏离零时 \\(m\\) 的条件期望并不在中点。本课钉微观价格：把最优档几何收成仍以货币为单位的标记。不重讲核函数估计。与 <a href="/quant/depth-mid">深度加权中间价</a> 的分工是 BBO 对多档；后课默认 \\(m^\\ast\\) 相对中点的偏离与 \\(I_1\\) 共线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Hawkes 给出到达强度，标记存货仍缺一个把簿几何收成货币的读数。做市与短窗信号都需要一个「现在的价」：标记存货、判断吃哪一侧、衡量有效价差。用成交价会弹跳；用中点会忽略深度不对称；用微价格是在问：若下一笔随机主动单到来，期望成交价或期望中点移动指向哪里。问题是把簿几何收成一个标量价格，既要能高频更新，又不要把瞬时队列噪声当成价值发现。</p><p>第二个问题是命名。文献里 microprice、weighted mid、imbalance-adjusted mid 经常混用。有的公式用 \\(I_1\\) 对 \\(b_1,a_1\\) 线性插值，与上式相同；有的把权放到多档，那是下一篇的深度加权。必须先锁定价位范围，再谈它预测的是下一跳中点、下一笔成交价，还是更长窗的有效价格。</p><h3 id="最优档加权把中间价推向薄侧" tabindex="-1">最优档加权把中间价推向薄侧 <a class="header-anchor" href="#最优档加权把中间价推向薄侧" aria-label="Permalink to &quot;最优档加权把中间价推向薄侧&quot;">​</a></h3><p>上式等价于 \\(m^\\ast=I_1 a_1+(1-I_1)b_1\\) 在 \\(I_1=q^b_1/(q^b_1+q^a_1)\\) 时的写法（注意此处 \\(I_1\\) 是买量份额，与有符号不平衡只差一个仿射变换）。\\(q^b_1\\gg q^a_1\\) 时 \\(m^\\ast\\approx a_1\\)：市场更可能在卖价成交或把中点推向卖价。价差 \\(s=a_1-b_1\\) 内，\\(m^\\ast\\) 相对 \\(m\\) 的偏离是</p> \\[m^\\ast-m=\\frac{s}{2}\\cdot\\frac{q^b_1-q^a_1}{q^b_1+q^a_1}, \\]<p>即半价差乘有符号不平衡。微价格相对中点的「信号」与 \\(I_1\\) 完全共线，只是带了 \\(s/2\\) 的单位。tick 大、价差常钉在一档时，这个偏离可达半个 tick，对做市报价有一等意义；价差极窄时偏离小于噪声。</p><p><span class="marginnote">数字实例：买档挂 100 手、卖档挂 20 手、价差 \\(s=0.02\\) 元，则 \\(I_1=100/120\\approx 0.83\\)，\\(m^\\ast-m=(0.02/2)\\times(100-20)/120\\approx 0.0067\\) 元——读数被推离中点约三分之二的半价差，偏向只有 20 手、更容易被打穿的卖档，而不是几何中点。</span></p><p><span class="marginnote">不要把 \\(m^\\ast\\) 当成可以无冲击成交的价格。立刻买仍付 \\(a_1\\)，立刻卖仍得 \\(b_1\\)。微价格是标记与预测用的读数，不是第三种可执行报价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 L2 快照上，每次 BBO 或最优档量变化就重算 \\(m^\\ast\\)。时间戳与 <a href="/quant/event-time">事件时间</a> 对齐。预测检验：用 \\(m^\\ast_t-m_t\\) 回归随后 \\(\\Delta m\\)，短窗应显著为正——中点向微价格靠拢。这是几何均值回复，不是价值发现的证明。对照应包括纯 \\(I_1\\)、纯 OFI：三者共线时，报告哪一个在给定延迟下更稳即可，不必三个都当独立因子。</p><p>标记存货时，用 \\(m^\\ast\\) 比用 \\(m\\) 更少在一侧深度被抽空时假装「公允价没动」。有效价差若仍相对 \\(m\\) 计算，会与微价格信号重复计算不平衡。研究应预先声明标记价。跨合约比较时，\\(m^\\ast-m\\) 有价格单位，除以 \\(s\\) 或除以 tick 后才可截面排序。</p><p><span class="marginnote">为什么重要：做市商用中点 \\(m\\) 标记存货时，买侧深度正被大单抽干的那一刻，\\(m\\) 还没动，账面盈亏看起来风平浪静；换成 \\(m^\\ast\\)，读数会先一步偏向被抽空的一侧，提前把「公允价要动了」写进标记。标记价选错，风控看到的回撤永远慢半拍。</span></p><h3 id="向微观价格的均值回复" tabindex="-1">向微观价格的均值回复 <a class="header-anchor" href="#向微观价格的均值回复" aria-label="Permalink to &quot;向微观价格的均值回复&quot;">​</a></h3><p>若主动单方向近似随机、深度暂时固定，中点的下一步期望指向薄侧，于是 \\(m\\) 向 \\(m^\\ast\\) 移动。一旦发生移动或增撤，\\(m^\\ast\\) 自己也跳，回复目标在走。因此「回归到微价格」是对极短窗、深度尚未重写时的条件陈述。窗一长，OFI 累积、冰山补量、暗池成交都会让目标失效。经验上数十毫秒到数秒常见显著；数分钟往往被公开信息和趋势淹没。</p><p>Stoikov 把微价格做成做市中间报价的候选：存货围绕 \\(m^\\ast\\) 而不是 \\(m\\) 来偏置，相当于把可见不平衡提前写进报价。这与 Glosten–Milgrom 的信念更新不同：那里移动的是对 \\(V\\) 的期望，这里移动的是对下一跳几何的期望。两者可以同时存在——先用 \\(m^\\ast\\) 处理几何，再用成交方向更新信息。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制就是队列不对称下的消耗。不需要知情者，也不需要 Kyle 的批量拍卖：只要市价单沿现有 BBO 到达，薄侧先破。O&#39;Hara 框架里订单流仍可携带信息，于是 \\(m^\\ast-m\\) 里混有信念成分；要把几何从信息里分开，可看不平衡在随后是否反转（几何耗尽后深度重建）还是变成永久中点移动（信息）。<a href="/quant/spread-decomposition">价差分解</a> 的暂时/永久切分在这里同样有用。</p>',21)),(E(),i(n,null,{default:e(()=>[o(s,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMB%5B%22%E8%A7%82%E6%B5%8B%E5%88%B0%E4%B8%8D%E5%B9%B3%E8%A1%A1%E5%81%8F%E7%A6%BB%E9%9B%B6%22%5D%20--%3E%20NEXT%5B%22%E7%9C%8B%E9%9A%8F%E5%90%8E%E6%B7%B1%E5%BA%A6%E4%B8%8E%E4%B8%AD%E7%82%B9%E6%80%8E%E4%B9%88%E8%B5%B0%22%5D%0A%20%20NEXT%20--%3E%20R1%5B%22%E6%B7%B1%E5%BA%A6%E8%A1%A5%E5%9B%9E%E3%80%81%E4%B8%AD%E7%82%B9%E5%BC%B9%E5%9B%9E%EF%BC%9A%E7%BA%AF%E5%87%A0%E4%BD%95%E6%B6%88%E8%80%97%22%5D%0A%20%20NEXT%20--%3E%20R2%5B%22%E4%B8%AD%E7%82%B9%E4%B8%8D%E5%86%8D%E5%9B%9E%E6%9D%A5%EF%BC%9A%E5%90%AB%E4%BF%A1%E6%81%AF%E6%88%90%E5%88%86%22%5D%0A%20%20NEXT%20--%3E%20R3%5B%22%E5%A4%A7%E5%8D%95%E8%BF%9B%E9%98%9F%E9%9A%8F%E5%8D%B3%E6%92%A4%E8%B5%B0%EF%BC%9A%E9%98%9F%E5%88%97%E5%99%AA%E5%A3%B0%22%5D%0A%20%20R1%20--%3E%20A1%5B%22%E9%80%82%E5%90%88%E7%9F%AD%E7%AA%97%E6%A0%87%E8%AE%B0%E4%B8%8E%E6%8A%A5%E4%BB%B7%E5%81%8F%E7%BD%AE%22%5D%0A%20%20R2%20--%3E%20A2%5B%22%E9%9C%80%E8%A6%81%20Glosten%E2%80%93Milgrom%20%E5%BC%8F%E4%BF%A1%E5%BF%B5%E6%9B%B4%E6%96%B0%22%5D%0A%20%20R3%20--%3E%20A3%5B%22%E8%AE%A1%E5%85%A5%E5%BE%AE%E4%BB%B7%E6%A0%BC%E7%9A%84%E6%B5%8B%E9%87%8F%E8%AF%AF%E5%B7%AE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<p>与 Hasbrouck 有效价格对照：有效价格是随机游走成分，微价格是当前簿的函数，通常高度平稳、随 \\(I_1\\) 抖动。把 \\(m^\\ast\\) 序列拿去估信息份额没有意义，它不是另一个市场的报价，而是同一张簿的另一种读数。<a href="/quant/hasbrouck-is">Hasbrouck 信息份额</a> 需要多市场或至少多个带噪声的价格序列共享共同趋势。</p><p><span class="marginnote">术语翻译：Hasbrouck 有效价格是把多个含噪声的报价做信号提取后剩下的随机游走成分，代表市场对价值的共识；微价格则是同一张订单簿的另一种加权读数，随不平衡高频抖动。前者回答「信息藏在哪个市场」，后者回答「簿现在长什么样」，不是一个层面的对象。</span></p><h3 id="与有效价格、信息份额不是同一对象" tabindex="-1">与有效价格、信息份额不是同一对象 <a class="header-anchor" href="#与有效价格、信息份额不是同一对象" aria-label="Permalink to &quot;与有效价格、信息份额不是同一对象&quot;">​</a></h3><p>微观结构噪声文献把观测价写成有效价加定价误差。中点、成交价、微价格都是候选观测。微价格可能减小与深度相关的那一部分误差，但会引入队列噪声：大单进队、随即撤走，\\(m^\\ast\\) 大幅跳动而有效价值未变。高频已实现波动若用 \\(m^\\ast\\) 会与用 \\(m\\) 不同，不能直接比较。选择哪一个做 RV，取决于你想滤掉的是买卖弹跳还是深度抖动。</p><p><span class="marginnote">冰山使显示 \\(q\\) 偏小，微价格会过度推向「看似薄」的一侧。这与队列因子相同的测量误差。检测补量模式可以修正 \\(m^\\ast\\)，仍属研究口径，不是展示策略。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(q^b_1+q^a_1\\to 0\\) 时公式崩溃，应回退到中点或暂停信号。涨跌停一侧无对手价，微价格无定义。集合竞价没有连续 BBO 的同一含义。多档深度与隐藏量被忽略，大单的冲击路径看 <a href="/quant/depth-mid">深度加权中间价</a>。最小报价单位使 \\(m^\\ast\\) 往往不是可报价网格上的点，做市商还要再圆整，圆整误差在一档价差时不可忽略。</p><p>不要用微价格变化当成交方向的替代去估 PIN：它不是买卖计数。不要把它与 OFI 同时当正交特征。延迟下，\\(m^\\ast\\) 比 \\(m\\) 更吵，信号可能先于稳定的中点消失。A 股三档或五档行情若没有可靠的最优档量，公式退化。</p><p><span class="marginnote">\\(m^\\ast\\) 对最优档的一个大单极为敏感。风控标记若用微价格，需对单笔占该档比例设上限，否则某人的一张可见单就能把你的存货盈亏刷成另一副样子——这是标记脆弱，不一定是信息。</span></p>',9)),(E(),i(n,null,{default:e(()=>[o(s,{id:"mermaid-87",class:"mermaid",graph:"flowchart%20TD%0A%20%20BBO%5B%22b1%2C%20a1%22%5D%20--%3E%20Mid%5B%22%E4%B8%AD%E9%97%B4%E4%BB%B7%20m%22%5D%0A%20%20Q%5B%22q%5Eb%2C%20q%5Ea%22%5D%20--%3E%20MP%5B%22%E5%BE%AE%E4%BB%B7%E6%A0%BC%20m*%22%5D%0A%20%20BBO%20--%3E%20MP%0A%20%20MP%20--%3E%20Gap%5B%22m*%20-%20m%20%E2%88%9D%20s%20%C2%B7%20%E4%B8%8D%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20Gap%20--%3E%20Pred%5B%22%E7%9F%AD%E7%AA%97%E4%B8%AD%E7%82%B9%E5%90%91%20m*%20%E9%9D%A0%E6%8B%A2%22%5D%0A%20%20Hidden%5B%22%E5%86%B0%E5%B1%B1%20%2F%20%E6%92%A4%E5%8D%95%22%5D%20-.-%3E%7C%22q%20%E6%8A%96%E5%8A%A8%22%7C%20MP%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t("h2",{id:"小结",tabindex:"-1"},[r("小结 "),t("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=t("ul",null,[t("li",null,"微观价格用最优档量加权买卖价，把读数推向薄侧；相对中点的偏离等于半价差乘不平衡。"),t("li",null,"它是标记与极短窗预测的几何读数，不是可执行报价，也不是 Hasbrouck 有效价格。"),t("li",null,"\\(m^\\ast-m\\) 与 \\(I_1\\) 共线；与 OFI、多档深度加权应分工而不是堆叠。"),t("li",null,"向微价格的靠拢在深度尚未重写的短窗成立，更长窗被流量与信息主导。"),t("li",null,"冰山、极薄档、涨跌停与圆整构成使用边界。"),t("li",null,"出处：Stoikov 对 micro-price 的讨论；簿事件与冲击见 Cont, Kukanov and Stoikov, 2014；有效价格语言见 Hasbrouck, 1993/1995。")],-1))])}const f=m(A,[["render",d]]);export{D as __pageData,f as default};
